const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];
const BRL = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const PCT = new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const INCOME_CATEGORIES = ['Vendas do balcão', 'Bebidas', 'Porções e cozinha', 'Delivery', 'Eventos', 'Outros'];
const EXPENSE_CATEGORIES = ['Compra de mercadorias', 'Fornecedores', 'Aluguel', 'Energia elétrica', 'Água', 'Gás', 'Funcionários', 'Taxas de cartão', 'Impostos', 'Manutenção', 'Embalagens e delivery', 'Outros'];
const state = { page: 'dashboard', period: 'month', reportPeriod: 'month', overview: null, report: null, editId: null, transactionStart: '', transactionEnd: '', toastTimer: null };

function isoToday() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function monthStartIso() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`; }
function weekStartIso() { const d = new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return fmtDateISO(d); }
function fmtDateISO(d) { return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function dateLabel(value, withYear = false) { if (!value) return '—'; const d = new Date(`${value}T12:00:00`); return d.toLocaleDateString('pt-BR', withYear ? { day:'2-digit',month:'short',year:'numeric' } : { day:'2-digit',month:'short' }).replace('.', ''); }
function rangeLabel(a,b) { if (!a || !b) return ''; return a === b ? dateLabel(a,true) : `${dateLabel(a,true)} – ${dateLabel(b,true)}`; }
function safe(v) { return String(v ?? '').replace(/[&<>"']/g, s => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s])); }
function fmt(value) { return BRL.format(Number(value || 0)); }
function fmtPct(value) { return `${PCT.format(Number(value || 0))}%`; }
function pctText(value) { if (value === null || value === undefined) return 'Novo'; const n = Number(value); return `${n > 0 ? '+' : ''}${PCT.format(n)}%`; }
function deltaClass(value, inverse = false) { if (value === null || value === undefined || Number(value) === 0) return 'neutral'; const good = inverse ? Number(value) < 0 : Number(value) > 0; return good ? 'positive' : 'negative'; }
function setChange(selector, value, inverse = false) { const el = $(selector); el.textContent = pctText(value); el.className = `metric-change ${deltaClass(value,inverse)}`; }
function queryDateParams(period = state.period) { if (period === 'custom') return `period=custom&start=${encodeURIComponent($('#dateStart').value)}&end=${encodeURIComponent($('#dateEnd').value)}`; return `period=${encodeURIComponent(period)}`; }
async function api(url, options = {}) { const response = await fetch(url, { credentials:'same-origin', headers: { 'Content-Type':'application/json', ...(options.headers||{}) }, ...options }); if (response.status === 401) { const overlay=$('#loginOverlay'); if(overlay) overlay.hidden=false; const logout=$('#logoutButton'); if(logout) logout.hidden=true; } if (!response.ok) { let message = 'Não foi possível concluir a operação.'; try { const data = await response.json(); message = Array.isArray(data.detail) ? data.detail.map(i=>i.msg).join('; ') : (data.detail || message); } catch {} throw new Error(message); } if (response.status === 204) return null; return response.json(); }

function initDates() { const start = monthStartIso(), end = isoToday(); $('#dateStart').value = start; $('#dateEnd').value = end; $('#listStart').value = start; $('#listEnd').value = end; state.transactionStart = start; state.transactionEnd = end; $('#footerYear').textContent = new Date().getFullYear(); }
function closeMobileMenu() { const sidebar = $('#sidebar'); if (!sidebar) return; sidebar.classList.remove('mobile-open'); sidebar.removeAttribute('style'); const menuButton = $('#mobileMenu'); if (menuButton) menuButton.setAttribute('aria-expanded', 'false'); }
function setPage(page) { state.page = page; $$('.page-section').forEach(el => el.classList.toggle('active', el.id === `page-${page}`)); $$('.nav-item').forEach(el => el.classList.toggle('active', el.dataset.page === page)); const names = {dashboard:'Visão geral',transactions:'Lançamentos',reports:'Relatórios'}; $('#breadcrumbCurrent').textContent = names[page] || names.dashboard; closeMobileMenu(); if (page === 'transactions') loadTransactions(); if (page === 'reports') loadReport(); if (page === 'dashboard') loadOverview(); window.scrollTo({top:0,behavior:'smooth'}); }
function setPeriod(period) { state.period = period; $$('.period-tabs:not(.report-tabs) button').forEach(el => el.classList.toggle('selected', el.dataset.period === period)); if (period === 'custom') $('#dateFields').style.display = 'flex'; else { $('#dateFields').style.display = 'flex'; loadOverview(); } }
async function loadOverview() { try { const data = await api(`/api/overview?${queryDateParams()}`); state.overview = data; const s = data.summary; $('#periodLabel').textContent = rangeLabel(s.start,s.end); $('#metricIncome').textContent = fmt(s.income); $('#metricExpenses').textContent = fmt(s.expenses); $('#metricNet').textContent = fmt(s.net); $('#metricNet').style.color = s.net < 0 ? '#c4625b' : '#1b2634'; $('#metricMargin').textContent = fmtPct(s.margin_pct); setChange('#incomeChange',data.changes.income); setChange('#expensesChange',data.changes.expenses,true); setChange('#netChange',data.changes.net); const marginEl = $('#marginChange'); marginEl.textContent = `${data.changes.margin_pct > 0 ? '+' : ''}${PCT.format(data.changes.margin_pct)} p.p.`; marginEl.className = `metric-change ${deltaClass(data.changes.margin_pct)}`; $('#expenseRatio').textContent = fmtPct(s.expense_ratio_pct); $('#transactionsCount').textContent = `${s.transactions} ${s.transactions === 1 ? 'lançamento' : 'lançamentos'}`; $('#navCount').textContent = s.transactions; const incomeScale = Math.max(s.income,s.expenses,1); $('#incomeTrack').style.width = `${Math.min(100,s.income/incomeScale*100)}%`; $('#expenseTrack').style.width = `${Math.min(100,s.expenses/incomeScale*100)}%`; $('#netNote').textContent = s.net < 0 ? 'As saídas superaram as entradas' : 'Entradas menos saídas registradas'; $('#dailyChartCaption').textContent = s.start === s.end ? 'Movimentação do dia selecionado' : `Movimentação de ${dateLabel(s.start,true)} a ${dateLabel(s.end,true)}`; $('#chartRange').textContent = `${data.daily.length} ${data.daily.length === 1 ? 'dia' : 'pontos no gráfico'}`; renderBarChart($('#dailyChart'), data.daily, false); renderCategories(data.expense_categories,s.expenses); renderDayHighlights(data.expense_days); renderRecent(data.recent); } catch (error) { showToast(error.message,'error'); } }
function renderCategories(items,total) { const el = $('#categoryList'); $('#categoryTotal').textContent = fmt(total); if (!items.length) { el.innerHTML = '<div class="empty-state compact">Registre despesas para ver a distribuição por categoria.</div>'; return; } const max = Math.max(...items.map(x=>x.value),1); el.innerHTML = items.slice(0,5).map(item=>`<div class="category-item"><div class="category-title"><span title="${safe(item.category)}">${safe(item.category)}</span><strong>${fmt(item.value)}</strong></div><div class="category-track"><span style="width:${Math.max(2,item.value/max*100)}%"></span></div></div>`).join(''); }
function renderDayHighlights(data) { const high = data.highest, low = data.lowest; $('#highestDayValue').textContent = high ? fmt(high.value) : '—'; $('#highestDayDate').textContent = high ? dateLabel(high.date,true) : 'Nenhuma saída registrada'; $('#lowestDayValue').textContent = low ? fmt(low.value) : '—'; $('#lowestDayDate').textContent = low ? dateLabel(low.date,true) : 'Nenhuma saída registrada'; }
function movementTitle(item) { return `<div class="movement-name"><div class="movement-symbol ${item.type === 'entrada'?'income':'expense'}">${item.type === 'entrada'?'↘':'↗'}</div><div><strong title="${safe(item.description)}">${safe(item.description)}</strong><small>${safe(item.category)}</small></div></div>`; }
function renderRecent(items) { const body = $('#recentRows'); if (!items.length) { body.innerHTML = '<tr><td colspan="3" class="table-empty">Ainda não há lançamentos neste período.</td></tr>'; return; } body.innerHTML = items.slice(0,6).map(item=>`<tr><td>${movementTitle(item)}</td><td>${dateLabel(item.date,true)}</td><td class="table-value ${item.type==='entrada'?'income':'expense'}">${item.type==='entrada'?'+':'−'} ${fmt(item.value)}</td></tr>`).join(''); }

function fitCanvas(canvas) { const rect=canvas.getBoundingClientRect(), dpr=window.devicePixelRatio||1; canvas.width=Math.max(1,Math.round(rect.width*dpr)); canvas.height=Math.max(1,Math.round(rect.height*dpr)); const ctx=canvas.getContext('2d'); ctx.setTransform(dpr,0,0,dpr,0,0); return {ctx,w:rect.width,h:rect.height}; }
function drawText(ctx,text,x,y,align='center',color='#9da6b0',size=9) { ctx.fillStyle=color;ctx.font=`${size}px 'DM Sans', sans-serif`;ctx.textAlign=align;ctx.fillText(String(text),x,y); }
function renderBarChart(canvas, data, trend = false) { if (!canvas) return; const {ctx,w,h}=fitCanvas(canvas); ctx.clearRect(0,0,w,h); const left=trend?34:36,right=10,top=10,bottom=30; const cw=Math.max(1,w-left-right), ch=Math.max(1,h-top-bottom); const values=data.flatMap(d=>[Number(d.income||0),Number(d.expenses||0)]); const max=Math.max(...values,1); const niceMax=max===0?1:max*1.16; for(let i=0;i<=4;i++){const y=top+ch*i/4;ctx.strokeStyle='#edf0f3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();const n=niceMax*(1-i/4);const label=n>=1000?`${(n/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})}k`:Math.round(n).toLocaleString('pt-BR');drawText(ctx,label,left-8,y+3,'right','#a6aeb8',8);} if(!data.length){drawText(ctx,'Sem movimentações neste período',w/2,h/2,'center','#a6aeb8',10);return;} const slot=cw/data.length, groupWidth=Math.min(trend?31:32,slot*.64), barWidth=Math.max(2,(groupWidth-4)/2); data.forEach((d,i)=>{const x=left+slot*i+slot/2;const hi=Number(d.income||0),he=Number(d.expenses||0);const h1=hi/niceMax*ch,h2=he/niceMax*ch;ctx.fillStyle='#4aa886';roundRect(ctx,x-groupWidth/2,top+ch-h1,barWidth,h1,3);ctx.fillStyle='#dc827c';roundRect(ctx,x-groupWidth/2+barWidth+4,top+ch-h2,barWidth,h2,3);const label=d.label||d.date||'';let show=true;const maxLabels=trend?8:9;const every=Math.max(1,Math.ceil(data.length/maxLabels));if(i%every!==0&&i!==data.length-1)show=false;if(show){let text=String(label);if(text.includes('-')&&text.length>7)text=text.slice(5,7)+'/'+text.slice(2,4);if(text.length>7)text=text.slice(0,7);drawText(ctx,text,x,h-9,'center','#98a2ad',8);}}); }
function roundRect(ctx,x,y,w,h,r) { if(h<=0||w<=0)return; r=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();ctx.fill(); }

async function loadTransactions() { try { const start=$('#listStart').value||monthStartIso(), end=$('#listEnd').value||isoToday(); state.transactionStart=start;state.transactionEnd=end; const type=$('#typeFilter').value; const q=$('#transactionSearch').value.trim();const data=await api(`/api/transactions?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&type=${encodeURIComponent(type)}&q=${encodeURIComponent(q)}&limit=5000`); const items=data.items; const income=items.filter(i=>i.type==='entrada').reduce((a,i)=>a+i.value,0);const expenses=items.filter(i=>i.type==='saida').reduce((a,i)=>a+i.value,0);$('#listIncome').textContent=fmt(income);$('#listExpenses').textContent=fmt(expenses);$('#listNet').textContent=fmt(income-expenses);$('#listNet').style.color=income-expenses<0?'#c4625b':'#1b2634';$('#listQty').textContent=data.count;$('#listStatus').textContent=`${data.count} ${data.count===1?'lançamento encontrado':'lançamentos encontrados'} · ${rangeLabel(start,end)}`;const body=$('#transactionRows');if(!items.length){body.innerHTML='<tr><td colspan="7" class="table-empty">Nenhum lançamento encontrado para estes filtros.</td></tr>';return;}body.innerHTML=items.map(item=>`<tr><td>${dateLabel(item.date,true)}</td><td><span class="type-pill ${item.type==='entrada'?'income':'expense'}">${item.type==='entrada'?'↘ Entrada':'↗ Saída'}</span></td><td><strong title="${safe(item.description)}" style="font-weight:700;color:#465363;max-width:210px;display:block;overflow:hidden;text-overflow:ellipsis">${safe(item.description)}</strong>${item.notes?`<small style="display:block;color:#a2abb5;margin-top:4px;max-width:210px;overflow:hidden;text-overflow:ellipsis">${safe(item.notes)}</small>`:''}</td><td><span class="category-chip" title="${safe(item.category)}">${safe(item.category)}</span></td><td>${safe(item.payment_method)}</td><td class="table-value ${item.type==='entrada'?'income':'expense'}">${item.type==='entrada'?'+':'−'} ${fmt(item.value)}</td><td><div class="row-actions"><button class="action-button" title="Editar lançamento" aria-label="Editar lançamento" data-edit="${item.id}">✎</button><button class="action-button delete" title="Excluir lançamento" aria-label="Excluir lançamento" data-delete="${item.id}">×</button></div></td></tr>`).join('');$('#navCount').textContent=(state.overview?.summary?.transactions ?? data.count); } catch(error){showToast(error.message,'error');} }

function categoriesFor(type) { return type==='entrada'?INCOME_CATEGORIES:EXPENSE_CATEGORIES; }
function fillCategoryOptions(type, selected='') { const options=categoriesFor(type); $('#categoryOptions').innerHTML=options.map(item=>`<option value="${safe(item)}"></option>`).join(''); if(selected) $('#txCategory').value=selected; else if(!options.includes($('#txCategory').value)) $('#txCategory').value=options[0]; }
function setMovementType(type) { $('#txType').value=type; $$('.type-choice').forEach(btn=>btn.classList.toggle('active',btn.dataset.type===type)); fillCategoryOptions(type); }
function openModal(item=null) { state.editId=item?.id??null; $('#movementForm').reset();$('#txId').value=item?.id??'';$('#txDate').value=item?.date||isoToday();$('#txDescription').value=item?.description||'';$('#txValue').value=item?Number(item.value).toFixed(2):'';$('#txPayment').value=item?.payment_method||'Dinheiro';$('#txNotes').value=item?.notes||'';$('#formFeedback').textContent='';$('#modalTitle').textContent=item?'Editar lançamento':'Novo lançamento';$('#saveMovement').innerHTML=item?'<span>✓</span> Salvar alterações':'<span>✓</span> Salvar lançamento';setMovementType(item?.type||'entrada');if(item)fillCategoryOptions(item.type,item.category);$('#movementModal').classList.add('open');$('#movementModal').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';setTimeout(()=>$('#txDescription').focus(),100); }
function closeModal() { $('#movementModal').classList.remove('open');$('#movementModal').setAttribute('aria-hidden','true');document.body.style.overflow='';state.editId=null; }
function showToast(message,type='success') { const el=$('#toast');el.textContent=message;el.className=`toast show ${type}`;if(state.toastTimer)clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.className='toast',3200); }
async function submitMovement(event) { event.preventDefault();const wasEditing=Boolean(state.editId);const value=Number($('#txValue').value);if(!Number.isFinite(value)||value<=0){$('#formFeedback').textContent='Informe um valor maior que zero.';return;}const body={date:$('#txDate').value,type:$('#txType').value,category:$('#txCategory').value.trim(),description:$('#txDescription').value.trim(),payment_method:$('#txPayment').value,value:Number(value.toFixed(2)),notes:$('#txNotes').value.trim()};if(!body.category||!body.description){$('#formFeedback').textContent='Preencha a descrição e a categoria.';return;}const submit=$('#saveMovement');submit.disabled=true;submit.textContent='Salvando…';try{if(state.editId)await api(`/api/transactions/${state.editId}`,{method:'PUT',body:JSON.stringify(body)});else await api('/api/transactions',{method:'POST',body:JSON.stringify(body)});closeModal();showToast(wasEditing?'Lançamento atualizado com sucesso.':'Lançamento salvo no banco de dados.');await Promise.all([loadOverview(),loadTransactions()]);if(state.page==='reports')await loadReport();}catch(error){$('#formFeedback').textContent=error.message;}finally{submit.disabled=false;submit.innerHTML='<span>✓</span> Salvar lançamento';} }
async function editTransaction(id) { try { const start='2000-01-01',end='2099-12-31';const data=await api(`/api/transactions?start=${start}&end=${end}&limit=5000`);const item=data.items.find(i=>i.id===Number(id));if(item)openModal(item);else showToast('Lançamento não encontrado.','error'); } catch(error){showToast(error.message,'error');} }
async function deleteTransaction(id) { const yes=window.confirm('Excluir este lançamento? Essa ação não pode ser desfeita.');if(!yes)return;try{await api(`/api/transactions/${id}`,{method:'DELETE'});showToast('Lançamento excluído.');await Promise.all([loadOverview(),loadTransactions()]);if(state.page==='reports')await loadReport();}catch(error){showToast(error.message,'error');} }

async function loadReport() { try { const data=await api(`/api/reports/compare?period=${state.reportPeriod}`);state.report=data;const current=data.current, previous=data.previous;$('#reportCurrentLabel').textContent=state.reportPeriod==='week'?'SALDO DA SEMANA ATUAL':'SALDO DO MÊS ATUAL';$('#reportCurrentNet').textContent=fmt(current.net);$('#reportCurrentNet').style.color=current.net<0?'#ffaaa0':'#fff';$('#reportNetDiff').textContent=`${pctText(data.changes.net)} no saldo`;$('#reportPreviousText').textContent=`Comparado ao ${state.reportPeriod==='week'?'semana':'mês'} anterior`;$('#reportIncome').textContent=fmt(current.income);$('#reportExpenses').textContent=fmt(current.expenses);$('#reportMargin').textContent=fmtPct(current.margin_pct);$('#reportIncomeDiff').textContent=pctText(data.changes.income);$('#reportExpensesDiff').textContent=pctText(data.changes.expenses);$('#reportExpensesDiff').classList.toggle('down',data.changes.expenses>0);$('#reportIncomeDiff').classList.toggle('down',data.changes.income<0);$('#reportMarginDiff').textContent=`${data.changes.margin_pct>0?'+':''}${PCT.format(data.changes.margin_pct)} p.p.`;$('#reportNetDiff').style.color=(data.changes.net??0)<0?'#ffb3ab':'#e7c28c';$('#reportPrevNet').textContent=fmt(previous.net);$('#reportNetDifference').textContent=fmt(current.net-previous.net);$('#reportNetDifference').style.color=current.net-previous.net<0?'#c4625b':'#2d9975';$('#reportExpenseRatio').textContent=fmtPct(current.expense_ratio_pct);$('#reportPeriodDate').textContent=rangeLabel(current.start,current.end);const high=data.expense_days.highest;$('#reportHighestDay').textContent=high?`${dateLabel(high.date,true)} · ${fmt(high.value)}`:'Sem saídas';$('#trendCaption').textContent=state.reportPeriod==='week'?'Evolução das últimas 8 semanas':'Evolução dos últimos 6 meses';$('#trendRange').textContent=data.trend.length?`${data.trend.length} períodos`:'';renderBarChart($('#trendChart'),data.trend,true);$('#reportTrendRows').innerHTML=[...data.trend].reverse().map(item=>`<tr><td><strong style="font-weight:700;color:#44505f">${safe(item.label)}</strong></td><td class="table-value income">${fmt(item.income)}</td><td class="table-value expense">${fmt(item.expenses)}</td><td class="table-value ${item.net<0?'expense':'income'}">${fmt(item.net)}</td><td class="table-value">${fmtPct(item.income?item.net/item.income*100:0)}</td></tr>`).join('');$$('[data-report-period]').forEach(btn=>btn.classList.toggle('selected',btn.dataset.reportPeriod===state.reportPeriod)); }catch(error){showToast(error.message,'error');} }
function exportCurrentPeriod() { const start=state.period==='custom'?$('#dateStart').value:state.overview?.summary?.start||monthStartIso();const end=state.period==='custom'?$('#dateEnd').value:state.overview?.summary?.end||isoToday();window.location.href=`/api/export.csv?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`; }
function exportListPeriod() { const start=$('#listStart').value||monthStartIso(),end=$('#listEnd').value||isoToday();window.location.href=`/api/export.csv?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`; }
function applyCustomDates() { const start=$('#dateStart').value,end=$('#dateEnd').value;if(!start||!end){showToast('Informe as duas datas do período.','error');return;}if(start>end){showToast('A data inicial não pode ser posterior à data final.','error');return;}state.period='custom';$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));loadOverview(); }
function setListFilterToDashboard() { const start=state.overview?.summary?.start||monthStartIso(),end=state.overview?.summary?.end||isoToday();$('#listStart').value=start;$('#listEnd').value=end; }
function bindEvents() {
  $$('.nav-item').forEach(btn=>btn.addEventListener('click',()=>setPage(btn.dataset.page)));$$('[data-open-page="transactions"]').forEach(btn=>btn.addEventListener('click',()=>{setListFilterToDashboard();setPage('transactions')}));
  $('#newMovementTop').addEventListener('click',()=>openModal());$('#newMovementList').addEventListener('click',()=>openModal());$('#sidebarNew').addEventListener('click',()=>openModal());$('#closeModal').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);$('#movementModal').addEventListener('click',e=>{if(e.target===$('#movementModal'))closeModal()});$('#movementForm').addEventListener('submit',submitMovement);$$('.type-choice').forEach(btn=>btn.addEventListener('click',()=>setMovementType(btn.dataset.type)));
  $$('.period-tabs:not(.report-tabs) button').forEach(btn=>btn.addEventListener('click',()=>{const period=btn.dataset.period;setPeriod(period);if(period==='custom'){ $('#dateFields').style.display='flex';$('#dateStart').focus();}}));$('#applyDates').addEventListener('click',applyCustomDates);$('#dateStart').addEventListener('change',()=>{if(state.period!=='custom'){$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));state.period='custom';}});$('#dateEnd').addEventListener('change',()=>{if(state.period!=='custom'){$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));state.period='custom';}});
  $('#applyListFilters').addEventListener('click',loadTransactions);$('#typeFilter').addEventListener('change',loadTransactions);let searchTimer;$('#transactionSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadTransactions,250)});$('#transactionRows').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)editTransaction(edit.dataset.edit);if(del)deleteTransaction(del.dataset.delete)});$('#exportList').addEventListener('click',exportListPeriod);$('#exportReport').addEventListener('click',()=>window.location.href=`/api/export.csv?start=${encodeURIComponent(state.report?.current.start||monthStartIso())}&end=${encodeURIComponent(state.report?.current.end||isoToday())}`);
  $$('[data-report-period]').forEach(btn=>btn.addEventListener('click',()=>{state.reportPeriod=btn.dataset.reportPeriod;loadReport()}));$('#backupButton').addEventListener('click',()=>{window.location.href='/api/backup';showToast('Backup do banco preparado para download.')});$('#mobileMenu').addEventListener('click',()=>{const sidebar=$('#sidebar');const opening=!sidebar.classList.contains('mobile-open');if(opening){sidebar.style.display='flex';sidebar.style.width='250px';sidebar.style.alignItems='stretch';sidebar.classList.add('mobile-open');$('#mobileMenu').setAttribute('aria-expanded','true');}else{closeMobileMenu();}});document.addEventListener('click',e=>{const sidebar=$('#sidebar');const menuButton=$('#mobileMenu');if(window.matchMedia('(max-width: 700px)').matches&&sidebar?.classList.contains('mobile-open')&&!sidebar.contains(e.target)&&!menuButton?.contains(e.target)){closeMobileMenu();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeMobileMenu();}});window.addEventListener('resize',()=>{if(state.overview)renderBarChart($('#dailyChart'),state.overview.daily,false);if(state.report)renderBarChart($('#trendChart'),state.report.trend,true);});
}

// Armazenamento local e cálculos de relatórios: não dependem da API financeira.
const LOCAL_DB_NAME = 'esquina-bar-local';
const LOCAL_DB_VERSION = 1;
let localDbPromise;
let migrationAction = 'import';

function openLocalDB() {
  if (!('indexedDB' in window)) return Promise.reject(new Error('Este navegador não oferece IndexedDB. Atualize o navegador para salvar os dados neste dispositivo.'));
  if (!localDbPromise) localDbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(LOCAL_DB_NAME, LOCAL_DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains('transactions')) {
        const store = db.createObjectStore('transactions', { keyPath: 'id', autoIncrement: true });
        store.createIndex('date', 'date', { unique: false });
        store.createIndex('type', 'type', { unique: false });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Não foi possível abrir o banco local.'));
    request.onblocked = () => reject(new Error('Feche outras abas do Esquina Bar e tente novamente.'));
  });
  return localDbPromise;
}
function idbRequest(request) { return new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error || new Error('Falha ao acessar os dados locais.')); }); }
async function listStored() { const db = await openLocalDB(); return idbRequest(db.transaction('transactions','readonly').objectStore('transactions').getAll()); }
async function getStored(id) { const db = await openLocalDB(); return idbRequest(db.transaction('transactions','readonly').objectStore('transactions').get(Number(id))); }
async function putStored(item) { const db = await openLocalDB(); return idbRequest(db.transaction('transactions','readwrite').objectStore('transactions').put(item)); }
async function addStored(item) { const db = await openLocalDB(); return idbRequest(db.transaction('transactions','readwrite').objectStore('transactions').add(item)); }
async function removeStored(id) { const db = await openLocalDB(); return idbRequest(db.transaction('transactions','readwrite').objectStore('transactions').delete(Number(id))); }
async function replaceStored(items) {
  const db = await openLocalDB();
  await new Promise((resolve,reject) => {
    const tx=db.transaction('transactions','readwrite'), store=tx.objectStore('transactions');
    store.clear(); for(const item of items) store.put(item);
    tx.oncomplete=()=>resolve(); tx.onerror=()=>reject(tx.error||new Error('Não foi possível restaurar o backup.')); tx.onabort=()=>reject(tx.error||new Error('A restauração foi cancelada.'));
  });
}
function viewStored(item) {
  const cents=Number.isInteger(item.amount_cents)?item.amount_cents:Math.round(Number(item.value||0)*100);
  return {...item,value:cents/100,date:item.date||item.movement_date,type:item.type||item.movement_type,payment_method:item.payment_method||'Dinheiro',notes:item.notes||''};
}
function toStored(movement, existing={}) {
  const value=Number(movement.value), date=String(movement.date||''), parsedDate=new Date(`${date}T12:00:00`);
  if(!Number.isFinite(value)||value<=0)throw new Error('O valor precisa ser maior que zero.');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(parsedDate.getTime())||fmtDateISO(parsedDate)!==date)throw new Error('Informe uma data válida.');
  if(!['entrada','saida'].includes(movement.type))throw new Error('Selecione entrada ou saída.');
  const category=String(movement.category||'').trim(),description=String(movement.description||'').trim();
  if(!category||!description)throw new Error('Preencha a descrição e a categoria.');
  if(category.length>100||description.length>180)throw new Error('A categoria ou descrição ultrapassou o limite permitido.');
  const now=new Date().toISOString();
  return {...existing,date,type:movement.type,category,description,payment_method:String(movement.payment_method||'Dinheiro').trim()||'Dinheiro',amount_cents:Math.round(value*100),notes:String(movement.notes||'').trim().slice(0,600),created_at:existing.created_at||now,updated_at:now};
}
function normalizeImportItem(item,preserveId=true) {
  if(!item||typeof item!=='object')throw new Error('O arquivo contém um lançamento inválido.');
  const date=String(item.date||item.movement_date||''),type=String(item.type||item.movement_type||'').toLowerCase();
  let cents;
  if(Number.isInteger(item.amount_cents))cents=item.amount_cents;
  else {const raw=item.value??item.amount??0;const parsed=typeof raw==='string'?(raw.includes(',')?Number(raw.replace(/\./g,'').replace(',','.')):Number(raw)):Number(raw);cents=Math.round(parsed*100);}
  const normalized=toStored({date,type,category:item.category,description:item.description,payment_method:item.payment_method||'Dinheiro',value:cents/100,notes:item.notes||''},{created_at:item.created_at||new Date().toISOString(),updated_at:item.updated_at||new Date().toISOString(),sourceServerId:item.sourceServerId??item.server_id??null});
  if(preserveId&&Number.isSafeInteger(Number(item.id))&&Number(item.id)>0)normalized.id=Number(item.id);
  if(item.sourceServerId!=null||item.server_id!=null)normalized.sourceServerId=Number(item.sourceServerId??item.server_id);
  return normalized;
}
function localDateObj(iso){return new Date(`${iso}T12:00:00`);}
function localDateRange(period,start,end){const today=isoToday();if(period==='today')return[today,today];if(period==='week'){const d=localDateObj(today);d.setDate(d.getDate()-((d.getDay()+6)%7));const a=fmtDateISO(d);d.setDate(d.getDate()+6);return[a,fmtDateISO(d)];}if(period==='month'){const d=localDateObj(today);return[fmtDateISO(new Date(d.getFullYear(),d.getMonth(),1,12)),fmtDateISO(new Date(d.getFullYear(),d.getMonth()+1,0,12))];}const a=start||monthStartIso(),b=end||today;if(a>b)throw new Error('A data inicial não pode ser posterior à data final.');return[a,b];}
function localPreviousRange(period,start,end){const a=localDateObj(start),b=localDateObj(end);if(period==='today'){a.setDate(a.getDate()-1);return[fmtDateISO(a),fmtDateISO(a)];}if(period==='week'){a.setDate(a.getDate()-7);b.setDate(b.getDate()-7);return[fmtDateISO(a),fmtDateISO(b)];}if(period==='month'){const last=new Date(a.getFullYear(),a.getMonth(),0,12);return[fmtDateISO(new Date(last.getFullYear(),last.getMonth(),1,12)),fmtDateISO(last)];}const length=Math.round((b-a)/86400000)+1,priorEnd=new Date(a);priorEnd.setDate(priorEnd.getDate()-1);const priorStart=new Date(priorEnd);priorStart.setDate(priorStart.getDate()-length+1);return[fmtDateISO(priorStart),fmtDateISO(priorEnd)];}
function storedCents(item){return Number.isInteger(item.amount_cents)?item.amount_cents:Math.round(Number(item.value||0)*100);}
function localPercentChange(current,previous){if(previous===0)return current===0?0:null;return Math.round((current-previous)/Math.abs(previous)*10000)/100;}
function localSummary(items,start,end){const rows=items.filter(i=>i.date>=start&&i.date<=end);let income=0,expenses=0,incomeCount=0,expenseCount=0;for(const item of rows){if(item.type==='entrada'){income+=storedCents(item);incomeCount++;}else{expenses+=storedCents(item);expenseCount++;}}const net=income-expenses;return{start,end,income:income/100,expenses:expenses/100,net:net/100,margin_pct:income?Math.round(net/income*10000)/100:0,expense_ratio_pct:income?Math.round(expenses/income*10000)/100:0,transactions:incomeCount+expenseCount,income_count:incomeCount,expense_count:expenseCount};}
function localDaily(items,start,end){const byDate=new Map();for(const item of items){if(item.date<start||item.date>end)continue;const key=item.date.slice(0,10);if(!byDate.has(key))byDate.set(key,{entrada:0,saida:0});byDate.get(key)[item.type]+=storedCents(item);}const days=Math.round((localDateObj(end)-localDateObj(start))/86400000)+1;if(days>100){const months=new Map();for(const[day,value]of byDate){const key=day.slice(0,7);if(!months.has(key))months.set(key,{entrada:0,saida:0});months.get(key).entrada+=value.entrada;months.get(key).saida+=value.saida;}return[...months.keys()].sort().map(key=>({date:key+'-01',label:key,income:months.get(key).entrada/100,expenses:months.get(key).saida/100}));}const result=[];let d=localDateObj(start);while(fmtDateISO(d)<=end){const key=fmtDateISO(d),value=byDate.get(key)||{entrada:0,saida:0};result.push({date:key,label:d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),income:value.entrada/100,expenses:value.saida/100});d.setDate(d.getDate()+1);}return result;}
function localExpenseDays(items,start,end){const days=new Map();for(const item of items){if(item.type==='saida'&&item.date>=start&&item.date<=end)days.set(item.date,(days.get(item.date)||0)+storedCents(item));}const values=[...days].map(([date,cents])=>({date,value:cents/100})).sort((a,b)=>b.value-a.value||a.date.localeCompare(b.date));return{highest:values[0]||null,lowest:values.length?[...values].sort((a,b)=>a.value-b.value||a.date.localeCompare(b.date))[0]:null};}
function localCategoryTotals(items,start,end,type){const map=new Map();for(const item of items){if(item.type!==type||item.date<start||item.date>end)continue;const x=map.get(item.category)||{category:item.category,cents:0,count:0};x.cents+=storedCents(item);x.count++;map.set(item.category,x);}return[...map.values()].map(x=>({category:x.category,value:x.cents/100,count:x.count})).sort((a,b)=>b.value-a.value);}
function localNewest(items){return[...items].sort((a,b)=>b.date.localeCompare(a.date)||(Number(b.id)||0)-(Number(a.id)||0));}
async function buildLocalOverview(period=state.period){const[start,end]=localDateRange(period,$('#dateStart').value,$('#dateEnd').value),items=(await listStored()).map(viewStored),summary=localSummary(items,start,end),[ps,pe]=localPreviousRange(period,start,end),previous=localSummary(items,ps,pe);return{summary,previous,changes:{income:localPercentChange(summary.income,previous.income),expenses:localPercentChange(summary.expenses,previous.expenses),net:localPercentChange(summary.net,previous.net),margin_pct:Math.round((summary.margin_pct-previous.margin_pct)*100)/100},daily:localDaily(items,start,end),expense_days:localExpenseDays(items,start,end),expense_categories:localCategoryTotals(items,start,end,'saida'),income_categories:localCategoryTotals(items,start,end,'entrada'),recent:localNewest(items.filter(i=>i.date>=start&&i.date<=end)).slice(0,8)};}
async function loadOverview(){try{const data=await buildLocalOverview();state.overview=data;const s=data.summary;$('#periodLabel').textContent=rangeLabel(s.start,s.end);$('#metricIncome').textContent=fmt(s.income);$('#metricExpenses').textContent=fmt(s.expenses);$('#metricNet').textContent=fmt(s.net);$('#metricNet').style.color=s.net<0?'#c4625b':'#1b2634';$('#metricMargin').textContent=fmtPct(s.margin_pct);setChange('#incomeChange',data.changes.income);setChange('#expensesChange',data.changes.expenses,true);setChange('#netChange',data.changes.net);const marginEl=$('#marginChange');marginEl.textContent=`${data.changes.margin_pct>0?'+':''}${PCT.format(data.changes.margin_pct)} p.p.`;marginEl.className=`metric-change ${deltaClass(data.changes.margin_pct)}`;$('#expenseRatio').textContent=fmtPct(s.expense_ratio_pct);$('#transactionsCount').textContent=`${s.transactions} ${s.transactions===1?'lançamento':'lançamentos'}`;$('#navCount').textContent=s.transactions;const scale=Math.max(s.income,s.expenses,1);$('#incomeTrack').style.width=`${Math.min(100,s.income/scale*100)}%`;$('#expenseTrack').style.width=`${Math.min(100,s.expenses/scale*100)}%`;$('#netNote').textContent=s.net<0?'As saídas superaram as entradas':'Entradas menos saídas registradas';$('#dailyChartCaption').textContent=s.start===s.end?'Movimentação do dia selecionado':`Movimentação de ${dateLabel(s.start,true)} a ${dateLabel(s.end,true)}`;$('#chartRange').textContent=`${data.daily.length} ${data.daily.length===1?'dia':'pontos no gráfico'}`;renderBarChart($('#dailyChart'),data.daily,false);renderCategories(data.expense_categories,s.expenses);renderDayHighlights(data.expense_days);renderRecent(data.recent);}catch(error){showToast(error.message,'error');}}
async function loadTransactions(){try{const start=$('#listStart').value||monthStartIso(),end=$('#listEnd').value||isoToday();if(start>end)throw new Error('A data inicial não pode ser posterior à data final.');state.transactionStart=start;state.transactionEnd=end;const type=$('#typeFilter').value,q=$('#transactionSearch').value.trim().toLocaleLowerCase('pt-BR');let items=(await listStored()).map(viewStored).filter(i=>i.date>=start&&i.date<=end);if(type!=='todos')items=items.filter(i=>i.type===type);if(q)items=items.filter(i=>[i.description,i.category,i.payment_method,i.notes].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(q)));items=localNewest(items);const income=items.filter(i=>i.type==='entrada').reduce((a,i)=>a+Math.round(i.value*100),0)/100,expenses=items.filter(i=>i.type==='saida').reduce((a,i)=>a+Math.round(i.value*100),0)/100;$('#listIncome').textContent=fmt(income);$('#listExpenses').textContent=fmt(expenses);$('#listNet').textContent=fmt(income-expenses);$('#listNet').style.color=income-expenses<0?'#c4625b':'#1b2634';$('#listQty').textContent=items.length;$('#listStatus').textContent=`${items.length} ${items.length===1?'lançamento encontrado':'lançamentos encontrados'} · ${rangeLabel(start,end)}`;const body=$('#transactionRows');if(!items.length){body.innerHTML='<tr><td colspan="7" class="table-empty">Nenhum lançamento encontrado para estes filtros.</td></tr>';return;}body.innerHTML=items.map(item=>`<tr><td>${dateLabel(item.date,true)}</td><td><span class="type-pill ${item.type==='entrada'?'income':'expense'}">${item.type==='entrada'?'↘ Entrada':'↗ Saída'}</span></td><td><strong title="${safe(item.description)}" style="font-weight:700;color:#465363;max-width:210px;display:block;overflow:hidden;text-overflow:ellipsis">${safe(item.description)}</strong>${item.notes?`<small style="display:block;color:#a2abb5;margin-top:4px;max-width:210px;overflow:hidden;text-overflow:ellipsis">${safe(item.notes)}</small>`:''}</td><td><span class="category-chip" title="${safe(item.category)}">${safe(item.category)}</span></td><td>${safe(item.payment_method)}</td><td class="table-value ${item.type==='entrada'?'income':'expense'}">${item.type==='entrada'?'+':'−'} ${fmt(item.value)}</td><td><div class="row-actions"><button class="action-button" title="Editar lançamento" aria-label="Editar lançamento" data-edit="${item.id}">✎</button><button class="action-button delete" title="Excluir lançamento" aria-label="Excluir lançamento" data-delete="${item.id}">×</button></div></td></tr>`).join('');$('#navCount').textContent=state.overview?.summary?.transactions??items.length;}catch(error){showToast(error.message,'error');}}
async function submitMovement(event){event.preventDefault();const wasEditing=Boolean(state.editId),value=Number($('#txValue').value),body={date:$('#txDate').value,type:$('#txType').value,category:$('#txCategory').value.trim(),description:$('#txDescription').value.trim(),payment_method:$('#txPayment').value,value:Number(value.toFixed(2)),notes:$('#txNotes').value.trim()},submit=$('#saveMovement');if(!Number.isFinite(value)||value<=0){$('#formFeedback').textContent='Informe um valor maior que zero.';return;}submit.disabled=true;submit.textContent='Salvando…';try{const existing=state.editId?await getStored(state.editId):{},stored=toStored(body,existing||{});if(state.editId){stored.id=Number(state.editId);await putStored(stored);}else await addStored(stored);closeModal();showToast(wasEditing?'Lançamento atualizado neste dispositivo.':'Lançamento salvo neste dispositivo.');await Promise.all([loadOverview(),loadTransactions()]);if(state.page==='reports')await loadReport();}catch(error){$('#formFeedback').textContent=error.message;}finally{submit.disabled=false;submit.innerHTML='<span>✓</span> Salvar lançamento';}}
async function editTransaction(id){try{const item=await getStored(id);if(item)openModal(viewStored(item));else showToast('Lançamento não encontrado.','error');}catch(error){showToast(error.message,'error');}}
async function deleteTransaction(id){if(!window.confirm('Excluir este lançamento? Essa ação não pode ser desfeita.'))return;try{await removeStored(id);showToast('Lançamento excluído deste dispositivo.');await Promise.all([loadOverview(),loadTransactions()]);if(state.page==='reports')await loadReport();}catch(error){showToast(error.message,'error');}}
function localMonthShift(year,month,offset){const index=year*12+(month-1)+offset;return[Math.floor(index/12),index%12+1];}
function localWeeklyRange(reference,weeksAgo=0){const monday=new Date(reference.getFullYear(),reference.getMonth(),reference.getDate(),12);monday.setDate(monday.getDate()-((monday.getDay()+6)%7)-7*weeksAgo);const sunday=new Date(monday);sunday.setDate(sunday.getDate()+6);return[fmtDateISO(monday),fmtDateISO(sunday)];}
async function buildLocalReport(period){const items=(await listStored()).map(viewStored),today=localDateObj(isoToday());let start,end,priorStart,priorEnd,trend=[];if(period==='week'){[start,end]=localWeeklyRange(today,0);[priorStart,priorEnd]=localWeeklyRange(today,1);for(let i=7;i>=0;i--){const[a,b]=localWeeklyRange(today,i),sum=localSummary(items,a,b);trend.push({label:`${localDateObj(a).getDate().toString().padStart(2,'0')}/${(localDateObj(a).getMonth()+1).toString().padStart(2,'0')}`,start:a,end:b,income:sum.income,expenses:sum.expenses,net:sum.net});}}else{start=fmtDateISO(new Date(today.getFullYear(),today.getMonth(),1,12));end=fmtDateISO(new Date(today.getFullYear(),today.getMonth()+1,0,12));const last=new Date(today.getFullYear(),today.getMonth(),0,12);priorStart=fmtDateISO(new Date(last.getFullYear(),last.getMonth(),1,12));priorEnd=fmtDateISO(last);for(let offset=5;offset>=0;offset--){const[y,m]=localMonthShift(today.getFullYear(),today.getMonth()+1,-offset),a=fmtDateISO(new Date(y,m-1,1,12)),b=fmtDateISO(new Date(y,m,0,12)),sum=localSummary(items,a,b),label=new Date(y,m-1,1,12).toLocaleDateString('pt-BR',{month:'short'}).replace('.','').replace(/^./,c=>c.toUpperCase())+(y!==today.getFullYear()?`/${String(y).slice(-2)}`:'');trend.push({label,start:a,end:b,income:sum.income,expenses:sum.expenses,net:sum.net});}}const current=localSummary(items,start,end),previous=localSummary(items,priorStart,priorEnd);return{current,previous,changes:{income:localPercentChange(current.income,previous.income),expenses:localPercentChange(current.expenses,previous.expenses),net:localPercentChange(current.net,previous.net),margin_pct:Math.round((Number(current.margin_pct||0)-Number(previous.margin_pct||0))*100)/100},trend,expense_days:localExpenseDays(items,start,end)};}
async function loadReport(){try{const data=await buildLocalReport(state.reportPeriod);state.report=data;const current=data.current,previous=data.previous;$('#reportCurrentLabel').textContent=state.reportPeriod==='week'?'SALDO DA SEMANA ATUAL':'SALDO DO MÊS ATUAL';$('#reportCurrentNet').textContent=fmt(current.net);$('#reportCurrentNet').style.color=current.net<0?'#ffaaa0':'#fff';$('#reportNetDiff').textContent=`${pctText(data.changes.net)} no saldo`;$('#reportPreviousText').textContent=`Comparado ao ${state.reportPeriod==='week'?'semana':'mês'} anterior`;$('#reportIncome').textContent=fmt(current.income);$('#reportExpenses').textContent=fmt(current.expenses);$('#reportMargin').textContent=fmtPct(current.margin_pct);$('#reportIncomeDiff').textContent=pctText(data.changes.income);$('#reportExpensesDiff').textContent=pctText(data.changes.expenses);$('#reportExpensesDiff').classList.toggle('down',data.changes.expenses>0);$('#reportIncomeDiff').classList.toggle('down',data.changes.income<0);$('#reportMarginDiff').textContent=`${data.changes.margin_pct>0?'+':''}${PCT.format(data.changes.margin_pct)} p.p.`;$('#reportNetDiff').style.color=(data.changes.net??0)<0?'#ffb3ab':'#e7c28c';$('#reportPrevNet').textContent=fmt(previous.net);$('#reportNetDifference').textContent=fmt(current.net-previous.net);$('#reportNetDifference').style.color=current.net-previous.net<0?'#c4625b':'#2d9975';$('#reportExpenseRatio').textContent=fmtPct(current.expense_ratio_pct);$('#reportPeriodDate').textContent=rangeLabel(current.start,current.end);const high=data.expense_days.highest;$('#reportHighestDay').textContent=high?`${dateLabel(high.date,true)} · ${fmt(high.value)}`:'Sem saídas';$('#trendCaption').textContent=state.reportPeriod==='week'?'Evolução das últimas 8 semanas':'Evolução dos últimos 6 meses';$('#trendRange').textContent=data.trend.length?`${data.trend.length} períodos`:'';renderBarChart($('#trendChart'),data.trend,true);$('#reportTrendRows').innerHTML=[...data.trend].reverse().map(item=>`<tr><td><strong style="font-weight:700;color:#44505f">${safe(item.label)}</strong></td><td class="table-value income">${fmt(item.income)}</td><td class="table-value expense">${fmt(item.expenses)}</td><td class="table-value ${item.net<0?'expense':'income'}">${fmt(item.net)}</td><td class="table-value">${fmtPct(item.income?item.net/item.income*100:0)}</td></tr>`).join('');$$('[data-report-period]').forEach(btn=>btn.classList.toggle('selected',btn.dataset.reportPeriod===state.reportPeriod));}catch(error){showToast(error.message,'error');}}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function exportCsvLocal(start,end){const items=localNewest((await listStored()).map(viewStored).filter(i=>i.date>=start&&i.date<=end)).reverse(),rows=[['ID','Data','Tipo','Categoria','Descrição','Forma de pagamento','Valor (R$)','Observações'],...items.map(i=>[i.id,i.date,i.type==='entrada'?'Entrada':'Saída',i.category,i.description,i.payment_method,i.value.toFixed(2).replace('.',','),i.notes||''])],csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`esquina-bar-lancamentos-${start}-a-${end}.csv`);showToast(`${items.length} lançamento(s) exportado(s) para CSV.`);}
function exportCurrentPeriod(){const start=state.period==='custom'?$('#dateStart').value:state.overview?.summary?.start||monthStartIso(),end=state.period==='custom'?$('#dateEnd').value:state.overview?.summary?.end||isoToday();if(start>end){showToast('A data inicial não pode ser posterior à data final.','error');return;}exportCsvLocal(start,end).catch(e=>showToast(e.message,'error'));}
function exportListPeriod(){const start=$('#listStart').value||monthStartIso(),end=$('#listEnd').value||isoToday();if(start>end){showToast('A data inicial não pode ser posterior à data final.','error');return;}exportCsvLocal(start,end).catch(e=>showToast(e.message,'error'));}
function applyCustomDates(){const start=$('#dateStart').value,end=$('#dateEnd').value;if(!start||!end){showToast('Informe as duas datas do período.','error');return;}if(start>end){showToast('A data inicial não pode ser posterior à data final.','error');return;}state.period='custom';$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));loadOverview();}
function setListFilterToDashboard(){const start=state.overview?.summary?.start||monthStartIso(),end=state.overview?.summary?.end||isoToday();$('#listStart').value=start;$('#listEnd').value=end;}
async function backupJsonLocal(){try{const items=(await listStored()).map(viewStored).sort((a,b)=>Number(a.id)-Number(b.id)),payload={app:'Esquina Bar — Controle Financeiro',schemaVersion:1,exportedAt:new Date().toISOString(),transactionCount:items.length,transactions:items};downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),`esquina-bar-backup-${isoToday()}.json`);showToast(`Backup criado com ${items.length} lançamento(s).`);}catch(error){showToast(error.message,'error');}}
async function restoreJsonLocal(file){if(!file)return;try{const payload=JSON.parse(await file.text()),items=Array.isArray(payload)?payload:payload.transactions;if(!Array.isArray(items))throw new Error('O arquivo não parece ser um backup válido do Esquina Bar.');const normalized=items.map(item=>normalizeImportItem(item,true));if(!window.confirm(`O backup contém ${normalized.length} lançamento(s). A restauração substituirá os dados deste navegador. Faça outro backup antes de continuar. Deseja prosseguir?`))return;await replaceStored(normalized);showToast(`Backup restaurado: ${normalized.length} lançamento(s).`);await Promise.all([loadOverview(),loadTransactions(),loadReport()]);}catch(error){showToast(`Não foi possível restaurar: ${error.message}`,'error');}finally{$('#restoreFile').value='';}}
async function importLegacyServer(event){event.preventDefault();const button=$('#loginSubmit'),error=$('#loginError'),action=migrationAction;button.disabled=true;button.textContent='Conectando…';error.textContent='';try{const responseLogin=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#loginUsername').value.trim(),password:$('#loginPassword').value})});let loginData={};try{loginData=await responseLogin.json();}catch{}if(!responseLogin.ok)throw new Error(loginData.detail||'Não foi possível autenticar no servidor antigo.');if(action==='backup'){const remote=await fetch('/api/backup',{credentials:'same-origin'});if(!remote.ok){let detail='Não foi possível baixar o backup remoto.';try{detail=(await remote.json()).detail||detail;}catch{}throw new Error(detail);}const blob=await remote.blob();downloadBlob(blob,`esquina-bar-backup-remoto-${isoToday()}.sql`);await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});$('#loginOverlay').hidden=true;$('#loginPassword').value='';showToast('Backup SQL remoto baixado. Guarde-o em local seguro.');return;}const response=await fetch('/api/legacy-export.json',{credentials:'same-origin'});let data={};try{data=await response.json();}catch{}if(!response.ok)throw new Error(data.detail||'Não foi possível ler os dados antigos. Confira se o banco PostgreSQL ainda está disponível.');if(!Array.isArray(data.items))throw new Error('O servidor não devolveu uma lista válida de lançamentos.');const existing=await listStored(),bySource=new Map(existing.filter(x=>x.sourceServerId!=null).map(x=>[Number(x.sourceServerId),x]));let added=0,updated=0;for(const item of data.items){const sourceId=Number(item.id),old=bySource.get(sourceId),normalized=normalizeImportItem({...item,sourceServerId:sourceId},false);if(old){normalized.id=old.id;normalized.sourceServerId=sourceId;normalized.created_at=old.created_at||normalized.created_at;await putStored(normalized);updated++;}else{normalized.sourceServerId=sourceId;await addStored(normalized);added++;}}await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});$('#loginOverlay').hidden=true;$('#loginPassword').value='';showToast(`Migração concluída: ${added} novo(s), ${updated} atualizado(s).`);await Promise.all([loadOverview(),loadTransactions(),loadReport()]);}catch(err){await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'}).catch(()=>{});error.textContent=err.message;}finally{button.disabled=false;button.textContent=migrationAction==='backup'?'Baixar backup SQL':'Importar registros';}}
function openMigration(action='import'){migrationAction=action;$('#loginError').textContent='';$('#loginPassword').value='';$('#loginSubmit').textContent=action==='backup'?'Baixar backup SQL':'Importar registros';const description=$('#loginForm .login-description');if(description)description.textContent=action==='backup'?'Baixe uma cópia SQL do banco remoto antigo. Esta ação não altera nem exclui os registros.':'Use o acesso de administrador atual para copiar os lançamentos do servidor para este dispositivo. Os dados antigos não serão apagados do servidor.';$('#loginOverlay').hidden=false;$('#loginUsername').focus();}
function closeMigration(){migrationAction='import';$('#loginOverlay').hidden=true;$('#loginPassword').value='';$('#loginError').textContent='';$('#loginSubmit').textContent='Importar registros';}
function registerServiceWorker(){if('serviceWorker'in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname)))navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA não pôde ser ativado:',e));}
function bindEvents(){
  // Menu responsivo: o evento deve ficar na função de inicialização ativa.
  const mobileMenu = $('#mobileMenu');
  const sidebar = $('#sidebar');
  if (mobileMenu && sidebar) {
    mobileMenu.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      const opening = !sidebar.classList.contains('mobile-open');
      if (opening) {
        sidebar.classList.add('mobile-open');
        mobileMenu.setAttribute('aria-expanded', 'true');
      } else {
        closeMobileMenu();
      }
    });
    document.addEventListener('click', (event) => {
      if (window.matchMedia('(max-width: 700px)').matches &&
          sidebar.classList.contains('mobile-open') &&
          !sidebar.contains(event.target) &&
          !mobileMenu.contains(event.target)) {
        closeMobileMenu();
      }
    });
  }
  $$('.nav-item').forEach(btn=>btn.addEventListener('click',()=>setPage(btn.dataset.page)));$$('[data-open-page="transactions"]').forEach(btn=>btn.addEventListener('click',()=>{setListFilterToDashboard();setPage('transactions');}));
  $('#newMovementTop').addEventListener('click',()=>openModal());$('#newMovementList').addEventListener('click',()=>openModal());$('#sidebarNew').addEventListener('click',()=>openModal());$('#closeModal').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);$('#movementModal').addEventListener('click',e=>{if(e.target===$('#movementModal'))closeModal();});$('#movementForm').addEventListener('submit',submitMovement);$$('.type-choice').forEach(btn=>btn.addEventListener('click',()=>setMovementType(btn.dataset.type)));
  $$('.period-tabs:not(.report-tabs) button').forEach(btn=>btn.addEventListener('click',()=>{const period=btn.dataset.period;setPeriod(period);if(period==='custom'){$('#dateFields').style.display='flex';$('#dateStart').focus();}}));$('#applyDates').addEventListener('click',applyCustomDates);$('#dateStart').addEventListener('change',()=>{if(state.period!=='custom'){$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));state.period='custom';}});$('#dateEnd').addEventListener('change',()=>{if(state.period!=='custom'){$$('.period-tabs:not(.report-tabs) button').forEach(el=>el.classList.toggle('selected',el.dataset.period==='custom'));state.period='custom';}});
  $('#applyListFilters').addEventListener('click',loadTransactions);$('#typeFilter').addEventListener('change',loadTransactions);let searchTimer;$('#transactionSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadTransactions,250);});$('#transactionRows').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)editTransaction(edit.dataset.edit);if(del)deleteTransaction(del.dataset.delete);});$('#exportList').addEventListener('click',exportListPeriod);$('#exportReport').addEventListener('click',()=>exportCsvLocal(state.report?.current.start||monthStartIso(),state.report?.current.end||isoToday()).catch(e=>showToast(e.message,'error')));
  $$('[data-report-period]').forEach(btn=>btn.addEventListener('click',()=>{state.reportPeriod=btn.dataset.reportPeriod;loadReport();}));$('#backupButton').addEventListener('click',backupJsonLocal);$('#restoreButton').addEventListener('click',()=>$('#restoreFile').click());$('#restoreFile').addEventListener('change',e=>restoreJsonLocal(e.target.files?.[0]));$('#importServerButton').addEventListener('click',()=>openMigration('import'));$('#remoteSqlBackupButton').addEventListener('click',()=>openMigration('backup'));$('#closeMigration').addEventListener('click',closeMigration);$('#loginOverlay').addEventListener('click',e=>{if(e.target===$('#loginOverlay'))closeMigration();});$('#loginForm').addEventListener('submit',importLegacyServer);
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeMigration();closeMobileMenu();}});window.addEventListener('resize',()=>{if(state.overview)renderBarChart($('#dailyChart'),state.overview.daily,false);if(state.report)renderBarChart($('#trendChart'),state.report.trend,true);});
}
async function startApplication(){initDates();bindEvents();try{await openLocalDB();$('#loginOverlay').hidden=true;await Promise.all([loadOverview(),loadTransactions(),loadReport()]);registerServiceWorker();}catch(error){showToast(error.message,'error');}}


startApplication();
